import java.util.Arrays;
import java.util.Scanner;


public class A151 {

	public static void main(String[] args) 
	{
		Scanner s = new Scanner(System.in);
		int n = s.nextInt(), l = s.nextInt() * s.nextInt(), d = s.nextInt() * s.nextInt(), p = s.nextInt(), 
				nl = n * s.nextInt(), nd = n, np = n * s.nextInt();
		int[] c = new int[3];
		c[0] = l / nl;
		c[1] = d / nd;
		c[2] = p / np;
		Arrays.sort(c);
		System.out.println(c[0]);
	}

}
